begin;
do $$ begin if (select version from public.restaurant_profile where id)<>1 or exists(select 1 from public.categories) or exists(select 1 from public.dishes) or exists(select 1 from public.ingredients) then raise exception 'EXAMPLE_CONTENT_REQUIRES_REVIEW'; end if; end $$;
update public.restaurant_profile set public_content=public_content||'{"hero_eyebrow": "Cernusco sul Naviglio · SACER", "hero_title": "Il gusto di stare insieme.", "hero_subtitle": "Una tavola da condividere, piatti da scoprire e tempo per ritrovarsi.", "hero_image_url": "https://ambrogiocorti.github.io/plateform-core/demo/tavola.jpg", "hero_image_alt": "Una tavola apparecchiata — fotografia dimostrativa", "story_title": "A tavola, insieme.", "story_intro": "La cucina come occasione per incontrarsi.", "story": "Una tavola apparecchiata è un invito a fermarsi. A condividere un piatto, una conversazione, un momento della giornata.\n\nQuesta pagina presenta un esempio del sito del ristorante: testi, piatti e fotografie mostrano come può essere raccontata la vostra cucina. I contatti della sede restano quelli configurati dal gestore.\n\nDai pranzi in compagnia alle occasioni speciali, ogni dettaglio può essere personalizzato: la storia, le immagini, la carta e le informazioni per chi viene a trovarvi.", "story_image_url": "https://ambrogiocorti.github.io/plateform-core/demo/sala.jpg", "story_image_alt": "Una sala ristorante luminosa — fotografia dimostrativa", "story_highlights": [{"title": "Una tavola aperta", "text": "Il piacere di incontrarsi, con il tempo giusto per stare insieme."}, {"title": "Una cucina da scoprire", "text": "Una carta leggibile, con ingredienti, prezzi e allergeni sempre vicini al piatto."}, {"title": "Le occasioni da ricordare", "text": "Pranzi, cene e momenti da condividere: contattaci per organizzare la tua visita."}], "gallery_intro": "Una selezione fotografica dimostrativa per esplorare il nuovo sito. Le immagini sono di Unsplash e non raffigurano la sede SACER.", "gallery": [{"url": "https://ambrogiocorti.github.io/plateform-core/demo/sala.jpg", "alt": "Gli spazi — immagine dimostrativa"}, {"url": "https://ambrogiocorti.github.io/plateform-core/demo/tavola.jpg", "alt": "La tavola — immagine dimostrativa"}, {"url": "https://ambrogiocorti.github.io/plateform-core/demo/cucina.jpg", "alt": "La cucina — immagine dimostrativa"}, {"url": "https://ambrogiocorti.github.io/plateform-core/demo/pasta.jpg", "alt": "I sapori — immagine dimostrativa"}], "menu_intro": "Una carta di esempio per esplorare il sito: piatti e prezzi sono dimostrativi, non un’offerta di vendita. Per il menu effettivo, contatta il ristorante.", "contacts_intro": "Ci trovi a Cernusco sul Naviglio, nella sede SACER. Per informazioni, orari e disponibilità usa i contatti qui sotto.", "footer": "Ristorante SACER · Cernusco sul Naviglio", "sections": {"story": true, "gallery": true, "contacts": true}, "example_content": true}'::jsonb where id and version=1;
commit;
